mapper.select:


    1 = 1

        AND l.title LIKE '%' || #{operLog.title} || '%'


        AND l.business_type = #{operLog.businessType}


        AND l.status = #{operLog.status}


        AND l.oper_name LIKE '%' || #{operLog.operName} || '%'


        AND l.oper_ip LIKE '%' || #{operLog.operIp} || '%'




                AND l.oper_time >= TO_TIMESTAMP(#{operLog.beginTime}, 'YYYY-MM-DD HH24:MI:SS')


                AND l.oper_time >= #{operLog.beginTime}






                AND l.oper_time <= TO_TIMESTAMP(#{operLog.endTime}, 'YYYY-MM-DD HH24:MI:SS')


                AND l.oper_time <= #{operLog.endTime}




ORDER BY l.oper_time DESC, l.oper_id DESC
